INSERT INTO public.systemscore (datescore, id_commentprofile, id_user) SELECT NOW(), (SELECT c.id FROM public.commentprofile c WHERE c.comment = 'Buen manejo de Angular, el catálogo está muy bien organizado.' AND c.id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres')), (SELECT id FROM public."user" WHERE username = 'developer') WHERE NOT EXISTS (SELECT 1 FROM public.systemscore WHERE id_commentprofile = (SELECT c.id FROM public.commentprofile c WHERE c.comment = 'Buen manejo de Angular, el catálogo está muy bien organizado.' AND c.id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres')));
